    'C': set(['A', 'F']),
    'D': set(['B']),
    'E': set(['B', 'F']),
    'F': set(['C', 'E'])
}

print(bfs(graph, 'A'))  # Output: {'A', 'B', 'C', 'D', 'E', 'F'}
```

