### Depth-First Search (DFS)

DFS is a recursive algorithm that explores as far as possible along each branch before backtracking. It uses a stack (in this case, implemented using a list) to keep track of nodes to visit.

```python
class Graph:
    def __init__(self, vertices):
        self.V = vertices
        self.graph = [[0 for _ in range(vertices)] for _ in range(vertices)]
        self.visited = [False] * vertices

    def add_edge(self, u, v):
        self.graph[u][v] = 1
        self.graph[v][u] = 1

    def is_cyclic_util(self, v, visited, rec_stack):
        visited[v] = True
        rec_stack[v] = True

        for neighbor in range(self.V):
            if self.graph[v][neighbor] and not visited[neighbor]:
                if self.is_cyclic_util(neighbor, visited, rec_stack):
                    return True
            elif rec_stack[neighbor]:
                return True

        rec_stack[v] = False
        return False

    def is_cyclic(self):
        visited = [False] * self.V
        rec_stack = [False] * self.V
        for node in range(self.V):
            if not visited[node]:
                if self.is_cyclic_util(node, visited, rec_stack):
                    return True
        return False

    def dfs(self, start_vertex):
        self.dfs_util(start_vertex, [])

    def dfs_util(self, u, stack):
        self.visited[u] = True
        stack.append(u)

        for neighbor in range(self.V):
            if self.graph[u][neighbor] and not self.visited[neighbor]:
                self.dfs_util(neighbor, stack)

        return stack

    def dfs_with_backtrack(self, start_vertex):
        stack = [start_vertex]
        path = [start_vertex]

        while stack:
            vertex = stack.pop()
            print(f"Visited vertex {vertex}")
            self.visited[vertex] = True

            for neighbor in range(self.V):
                if self.graph[vertex][neighbor] and not self.visited[neighbor]:
                    stack.append(neighbor)
                    path.append(neighbor)

        print("DFS Path:", path)
